// Runs on an Android device/emulator inside the real app (MainActivity,
// JNI_OnLoad, MediaCodec, dart:ffi, the Flutter renderer):
//
//   flutter test integration_test/preview_pipeline_test.dart -d <device>
//
// The media files are generated by scripts/make_android_test_media.sh into
// integration_test/media/ and bundled as assets for the test build only
// (see .github/workflows/android-tests.yml). Every result line starts with
// "PREVIEW-REPORT" so CI logs can be searched.
import 'dart:async';
import 'dart:io';
import 'dart:ui' as ui;

import 'package:cutlab/src/engine/ffi_media_engine.dart';
import 'package:cutlab/src/engine/media_engine.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:path_provider/path_provider.dart';

/// name -> has a picture
const videos = {
  'h264_1080p30.mp4': true,
  'h264_1080p60.mp4': true,
  'hevc_1080p60.mp4': true,
  'hevc10_4k30.mp4': true,
  'phone_portrait_1080p60.mp4': true,
  'long_720p30_10min.mp4': true,
  'vfr.mkv': true,
};
const others = ['tone.mp3', 'red.png'];
const broken = ['truncated.mp4', 'garbage.mp4', 'av1.mp4'];

const _channel = MethodChannel('cutlab/media');

void report(String line) {
  // ignore: avoid_print
  print('PREVIEW-REPORT $line');
}

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  late MediaEngine engine;
  final paths = <String, String>{};

  setUpAll(() async {
    engine = FfiMediaEngine.load();
    final dir = await getTemporaryDirectory();
    final manifest = await AssetManifest.loadFromAssetBundle(rootBundle);
    for (final key in manifest.listAssets()) {
      if (!key.startsWith('integration_test/media/')) continue;
      final name = key.substring('integration_test/media/'.length);
      final data = await rootBundle.load(key);
      final f = File('${dir.path}/$name');
      await f.writeAsBytes(data.buffer.asUint8List(data.offsetInBytes, data.lengthInBytes), flush: true);
      paths[name] = f.path;
    }
    report('media: ${paths.keys.join(', ')}');
  });

  /// Opens [name] the way the app opens Android media: a file descriptor
  /// from the ContentResolver ("fd:N"), closed afterwards.
  Future<T> withFd<T>(String name, Future<T> Function(String uri) body) async {
    final path = paths[name];
    if (path == null) fail('missing test media $name');
    final fd = await _channel.invokeMethod<int>('openFd', {'uri': Uri.file(path).toString()});
    expect(fd, isNotNull);
    try {
      return await body('fd:$fd');
    } finally {
      await _channel.invokeMethod<void>('closeFd', {'fd': fd});
    }
  }

  Future<ui.Image> toImage(RgbaImage f) {
    final c = Completer<ui.Image>();
    ui.decodeImageFromPixels(f.pixels, f.width, f.height, ui.PixelFormat.rgba8888, c.complete);
    return c.future;
  }

  /// Plays for [ms], scrubs, and returns what happened.
  Future<Map<String, Object>> play(String uri, {required bool hardware, int ms = 2000, int box = 1280}) async {
    final p = engine.openPlayer(uri, maxWidth: box, maxHeight: box, hardware: hardware);
    var frames = 0, w = 0, h = 0;
    Future<void> pump(int forMs) async {
      final sw = Stopwatch()..start();
      while (sw.elapsedMilliseconds < forMs) {
        await Future<void>.delayed(const Duration(milliseconds: 16));
        final f = p.pollFrame();
        if (f != null) {
          frames++;
          w = f.width;
          h = f.height;
          expect(f.pixels.length, f.width * f.height * 4);
          (await toImage(f)).dispose();
        }
      }
    }

    try {
      final dur = p.durationTicks;
      p.play();
      await pump(ms);
      for (var i = 0; i < 30; i++) {
        p.seek(dur * ((i * 37) % 100) ~/ 100, accurate: i % 6 == 5);
        await pump(10);
      }
      p.pause();
      p.seek(dur ~/ 2);
      await pump(400);
      p.play();
      await pump(500);
      final s = p.stats();
      return {'frames': frames, 'size': '${w}x$h', 'decoder': s.decoder, 'hardware': s.hardware, 'dropped': s.framesDropped, 'audio': s.audioDevice};
    } finally {
      p.dispose();
    }
  }

  testWidgets('engine loads with FFmpeg and MediaCodec', (tester) async {
    report('engine available=${engine.available} ffmpeg=${engine.info.ffmpegVersion} hw=${engine.info.hardwareDecoders} '
        'reason=${engine.info.reason}');
    expect(engine.available, isTrue, reason: engine.info.reason);
    expect(engine.info.hardwareDecoders, contains('h264_mediacodec'));
  });

  for (final name in videos.keys) {
    for (final hw in [true, false]) {
      testWidgets('$name plays (${hw ? 'hardware' : 'software'} decoding)', (tester) async {
        await tester.runAsync(() async {
          final r = await withFd(name, (uri) => play(uri, hardware: hw));
          report('$name hw=$hw $r');
          expect(r['frames'] as int, greaterThan(3), reason: '$r');
        });
      });
    }
  }

  testWidgets('frame, thumbnails and waveform for every file', (tester) async {
    await tester.runAsync(() async {
      for (final name in [...videos.keys, ...others]) {
        await withFd(name, (uri) async {
          final info = await engine.probe(uri);
          report('$name probe ${info.summary} ${info.width}x${info.height} rot=${info.rotation}');
          if (info.videoCodec != null) {
            final f = await engine.frameAt(uri, info.durationTicks ~/ 2, maxWidth: 640, maxHeight: 640);
            expect(f.pixels.length, f.width * f.height * 4);
            final strip = await engine.thumbnails(uri, 12, maxWidth: 96, maxHeight: 54);
            expect(strip.frames, isNotEmpty);
          }
          if (info.hasAudio) {
            final peaks = await engine.peaks(uri, bucketsPerSecond: 20);
            expect(peaks.length, greaterThan(0));
          }
        });
      }
    });
  });

  testWidgets('open and close the preview quickly, 25 times', (tester) async {
    await tester.runAsync(() async {
      for (var i = 0; i < 25; i++) {
        final name = videos.keys.elementAt(i % videos.length);
        await withFd(name, (uri) async {
          final p = engine.openPlayer(uri, maxWidth: 1280, maxHeight: 1280, hardware: i.isEven);
          p.play();
          await Future<void>.delayed(Duration(milliseconds: (i * 13) % 120));
          p.pollFrame();
          p.dispose();
        });
      }
      report('open/close x25 ok');
    });
  });

  testWidgets('broken and unsupported files fail without crashing', (tester) async {
    await tester.runAsync(() async {
      for (final name in broken) {
        if (!paths.containsKey(name)) continue;
        await withFd(name, (uri) async {
          for (final hw in [true, false]) {
            try {
              final p = engine.openPlayer(uri, hardware: hw);
              p.play();
              await Future<void>.delayed(const Duration(milliseconds: 500));
              p.pollFrame();
              report('$name hw=$hw opened: ${p.stats().decoder}');
              p.dispose();
            } on MediaEngineException catch (e) {
              report('$name hw=$hw error (expected): $e');
            }
          }
          try {
            await engine.frameAt(uri, 0);
          } on MediaEngineException catch (e) {
            report('$name frame error (expected): $e');
          }
        });
      }
    });
  });
}
